#!/usr/bin/env python3
"""
Run the TRELLIS GPU job on Kaggle's free T4 GPU from GitHub Actions, then download the GLB.

    KAGGLE_API_TOKEN=... python tools/kaggle_run.py rider_white_bg.png -o output/model.glb

The Kaggle account must be phone-verified (needed for GPU + internet).
Kaggle gives about 30 free GPU hours per week; one model uses roughly 25-35 minutes.
"""
import argparse
import base64
import json
import sys
import tempfile
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
TITLE = "image-to-glb-runner"

KERNEL_TEMPLATE = r'''
# Auto-generated by image-to-glb (tools/kaggle_run.py). Safe to delete.
import base64, subprocess, sys
from pathlib import Path

FILES = __FILES__
IMAGE_NAME = __IMAGE_NAME__
JOB = Path("/tmp/job")
for rel, b64 in FILES.items():
    p = JOB / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))

log = open("/kaggle/working/run_log.txt", "w")

def step(*args):
    cmd = [sys.executable, "-u", str(JOB / "gpu" / "trellis_gpu.py"), *args]
    proc = subprocess.Popen(cmd, cwd=JOB, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    for line in proc.stdout:
        print(line, end="", flush=True)
        log.write(line); log.flush()
    if proc.wait() != 0:
        raise SystemExit(f"step {args[0]} failed")

step("install")
step("generate", str(JOB / IMAGE_NAME), "-o", "/kaggle/working/model.glb",
     "--seed", "__SEED__", "--texture", "__TEXTURE__", "--simplify", "__SIMPLIFY__")
'''


def b64(path: Path) -> str:
    return base64.b64encode(path.read_bytes()).decode()


MAX_SIDE = 768        # TRELLIS works at 518 px, so bigger images only make the job file heavy
SMALL_ENOUGH = 300_000  # bytes; images this small are sent unchanged


def shrink_image(image: Path, folder: Path) -> Path:
    """The image travels inside the Kaggle job code as text, and Kaggle rejects big jobs
    (400 Bad Request). Make a small copy: PNG if it has transparency, otherwise JPEG."""
    if image.stat().st_size <= SMALL_ENOUGH:
        return image
    from PIL import Image
    with Image.open(image) as im:
        im.load()
        has_alpha = im.mode in ("RGBA", "LA", "PA") or "transparency" in im.info
        im = im.convert("RGBA" if has_alpha else "RGB")
        im.thumbnail((MAX_SIDE, MAX_SIDE), Image.LANCZOS)
        if has_alpha:
            out = folder / "input_small.png"
            im.save(out, "PNG", optimize=True)
        else:
            out = folder / "input_small.jpg"
            im.save(out, "JPEG", quality=92)
    print(f"Image made smaller for Kaggle: {image.stat().st_size / 1e6:.1f} MB -> "
          f"{out.stat().st_size / 1e6:.2f} MB ({im.size[0]}x{im.size[1]})")
    return out


def build_kernel(folder: Path, user: str, image: Path, args) -> str:
    small = shrink_image(image, folder.parent)
    image_name = "input" + small.suffix.lower()
    files = {
        "gpu/trellis_gpu.py": b64(ROOT / "gpu" / "trellis_gpu.py"),
        "glb_utils.py": b64(ROOT / "glb_utils.py"),
        image_name: b64(small),
    }
    code = (KERNEL_TEMPLATE
            .replace("__FILES__", json.dumps(files))
            .replace("__IMAGE_NAME__", json.dumps(image_name))
            .replace("__SEED__", str(args.seed))
            .replace("__TEXTURE__", str(args.texture))
            .replace("__SIMPLIFY__", str(args.simplify)))
    (folder / "run.py").write_text(code)
    print(f"Kaggle job file size: {len(code) / 1e6:.2f} MB")
    kernel_id = f"{user}/{TITLE}"
    meta = {
        "id": kernel_id,
        "title": TITLE,
        "code_file": "run.py",
        "language": "python",
        "kernel_type": "script",
        "is_private": True,
        "enable_gpu": True,
        "enable_internet": True,
        "machine_shape": "NvidiaTeslaT4",
        "dataset_sources": [],
        "competition_sources": [],
        "kernel_sources": [],
        "model_sources": [],
    }
    (folder / "kernel-metadata.json").write_text(json.dumps(meta, indent=2))
    return kernel_id


def kaggle_reason(err: Exception) -> str:
    """Pull Kaggle's own error message out of an HTTP error (it hides behind '400 Bad Request')."""
    resp = getattr(err, "response", None)
    if resp is None:
        return "(no details from Kaggle)"
    try:
        body = resp.json()
        if isinstance(body, dict):
            for key in ("message", "error", "errors", "detail"):
                if body.get(key):
                    return str(body[key])
        return json.dumps(body)
    except Exception:
        text = (getattr(resp, "text", "") or "").strip()
        return text[:2000] or "(empty reply from Kaggle)"


def status_of(api, kernel_id: str):
    resp = api.kernels_status(kernel_id)
    st = str(getattr(resp, "status", resp)).lower()
    msg = getattr(resp, "failure_message", "") or ""
    return st, msg


def print_log_tail(api, kernel_id: str, out_dir: Path, lines: int = 80):
    try:
        text = api.kernels_logs(kernel_id)
    except Exception as e:
        print(f"(could not fetch Kaggle log: {e})")
        return
    (out_dir / "kaggle_log.txt").write_text(text)
    print("----- last lines of the Kaggle log -----")
    try:  # Kaggle logs are a JSON list of {"data": "..."} entries
        text = "".join(item.get("data", "") for item in json.loads(text))
    except Exception:
        pass
    print("\n".join(text.splitlines()[-lines:]))


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("image")
    ap.add_argument("-o", "--output", default="output/model.glb")
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--texture", type=int, default=1024)
    ap.add_argument("--simplify", type=float, default=0.95)
    ap.add_argument("--timeout-min", type=int, default=100)
    args = ap.parse_args()

    image = Path(args.image)
    if not image.exists():
        print(f"Input not found: {image}. Give the path as it is in the repo, e.g. rider_white_bg.png")
        return 1
    out = Path(args.output)
    out.parent.mkdir(parents=True, exist_ok=True)

    from kaggle.api.kaggle_api_extended import KaggleApi
    api = KaggleApi()
    api.authenticate()
    user = api.config_values.get("username")
    if not user:
        print("Could not read your Kaggle username. Check the KAGGLE_API_TOKEN secret.")
        return 1
    print(f"Kaggle user: {user}")

    with tempfile.TemporaryDirectory() as tmp_root:
        tmp = Path(tmp_root) / "kernel"   # only the job files go in here
        tmp.mkdir()
        kernel_id = build_kernel(tmp, user, image, args)
        print(f"Starting Kaggle GPU job {kernel_id} ...")
        try:
            resp = api.kernels_push(str(tmp), acc="NvidiaTeslaT4")
        except Exception as e:
            print(f"Kaggle refused the job: {e}")
            print(f"Kaggle's reason: {kaggle_reason(e)}")
            print("Check: phone verified at kaggle.com/settings, GPU hours left this week.")
            return 1
        err = getattr(resp, "error", None)
        if err:
            print(f"Kaggle refused the job: {err}")
            print("Is your Kaggle account phone-verified? GPU + internet need it.")
            return 1
        url = getattr(resp, "url", None)
        if url:
            print(f"Watch it live: {url}")

    time.sleep(45)  # let Kaggle switch to the new version
    start = time.time()
    last = None
    while True:
        try:
            st, msg = status_of(api, kernel_id)
        except Exception as e:
            st, msg = "unknown", str(e)
        if st != last:
            print(f"[{int((time.time() - start) / 60)} min] status: {st}", flush=True)
            last = st
        if "complete" in st:
            break
        if "error" in st or "cancel" in st:
            print(f"Kaggle job failed. {msg}")
            print_log_tail(api, kernel_id, out.parent)
            print("If it says 'No NVIDIA GPU': verify your phone at kaggle.com/settings, "
                  "and check you still have GPU hours left this week.")
            return 2
        if time.time() - start > args.timeout_min * 60:
            print(f"Gave up after {args.timeout_min} minutes. The job may still finish on Kaggle: {kernel_id}")
            return 2
        time.sleep(30)

    dl = out.parent / "kaggle_output"
    dl.mkdir(parents=True, exist_ok=True)
    api.kernels_output(kernel_id, str(dl), force=True)
    glb = next(dl.rglob("model.glb"), None)
    if glb is None:
        print("Job finished but no model.glb came back.")
        print_log_tail(api, kernel_id, out.parent)
        return 2
    glb.replace(out)
    used = next(dl.rglob("input_used.png"), None)
    if used:
        used.replace(out.with_name("input_used.png"))
    print(f"Done: {out} ({out.stat().st_size / 1e6:.1f} MB) from Kaggle")
    return 0


if __name__ == "__main__":
    sys.exit(main())
